/* machine-generated by m2c: a starting point, not a match */
#ifndef M2C_DEFINES
#define M2C_DEFINES
typedef s32 M2C_UNK;
typedef s8 M2C_UNK8;
typedef s16 M2C_UNK16;
typedef s32 M2C_UNK32;
#define M2C_FIELD(expr, type_ptr, offset) (*(type_ptr)((s8 *)(expr) + (offset)))
#define M2C_BITWISE(type, expr) ((type)(expr))
#define M2C_ERROR(desc) (0)
#define M2C_CARRY 0
#define M2C_OVERFLOW(a) (0)
#endif

extern M2C_UNK gSinQuarterTable;

/* Fixed-point sine: angle is 12-bit (4096 per turn); uses a 1024-entry quarter-wave table with mirroring and negation. */ s16 sinFixed4096(s32 angle) {
    s32 index;
    u32 wrapped;

    wrapped = angle & 0xFFF;
    if (wrapped < 0x400U) {
        return *((s16 *)((s8 *)&gSinQuarterTable + (wrapped * 2)));
    }
    if (wrapped < 0x800U) {
        return *((s16 *)((s8 *)&gSinQuarterTable + ((~angle & 0x3FF) * 2)));
    }
    if (wrapped >= 0xC00U) {
        index = ~angle & 0x3FF;
    } else {
        index = angle & 0x3FF;
    }
    return (s16) ((s32) *((u16 *)((s8 *)&gSinQuarterTable + (index * 2))) * -1);
}
